    moderate_prev = 0.0
    if prev_bids:
        sorted_bids = sorted(prev_bids)
        moderate_prev = sorted_bids[int(len(sorted_bids) // 2)]

    req_pressure = len(alive_opponents) + 1
    if supply < WATER_REQ:
        scarcity = 1.0
    else:
        scarcity = req_pressure / max(1.0, supply / float(WATER_REQ))

    if hp <= 2 or no_water_days >= 2:
